var n=`0103-kugelis`;var o=`world-0103`;var t=`LT`;var l=`northern-europe`;var s=4;var a=78;var r={en:`Kugelis`,ua:`Куґеліс`};var g={en:`A classic dish from Lithuania, featuring potato, yellow onion, chicken egg, whole cow milk. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Литва. Основні складники: картопля, жовта цибуля, куряче яйце, цільне коров'яче молоко. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`potato`,950,`g`],[`yellow-onion`,130,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`chicken-egg`,3,`pcs`],[`whole-cow-milk`,160,`ml`],[`all-purpose-flour`,90,`g`],[`bacon`,160,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Bake in a preheated 180°C oven for about 60 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 60 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:60,i:[[`sunflower-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,140,`g`]]}];var c={slug:n,id:o,country:`LT`,region:l,servings:4,minutes:78,title:r,text:g,steps:u};export{t as country,c as default,o as id,a as minutes,l as region,s as servings,n as slug,u as steps,g as text,r as title};